 if(f>0&&g.x>hx[h]+5&&g.x<hx[h]+8.25f&&g.z>hz[h]-8.3f&&g.z<hz[h]-6.5f&&look_at(hx[h]+7.2f,f*3+1.8f,hz[h]-8.42f,.91f)){if(perform){g.stairWindows200[h]^=1u<<(16+f);audio(12);say("Окно подъезда: без проверки навыка.");save_game();}else SN(prompt,sizeof(prompt),"E — окно подъезда / открыть или закрыть");return 1;}
