 /* Direct kettle interactions in older panel apartments: previously only the stove was usable. */
 for(int p=0;p<PANEL_COUNT;p++){if(dst(g.x,g.z,panel_origin_x(p),panel_origin_z(p))>20)continue;int f=(int)clamp((float)floor((g.playerY+.1f)/3),0,3);for(int w=0;w<2;w++)for(int s=-1;s<=1;s+=2){float x=panel_origin_x(p)+(w?7:-7)+s*6.35f,z=panel_origin_z(p)-3.7f;int id=w*8+f*2+(s>0);if(dst(g.x,g.z,x,z)>2||!look_at(x,f*3+1.12f,z,.965f))continue;if(!perform){SN(prompt,sizeof(prompt),panelKettleHeat[p][id]>.85f?"E — налить горячий чай":"E — вскипятить чайник");return 1;}if(panelKettleHeat[p][id]>.85f){g.thirst=mn(100,g.thirst+32);g.stress=mx(0,g.stress-8);panelKettleHeat[p][id]=.1f;panelStoveOn[p][id]=0;say("Ты выпил горячий чай.");}else{panelStoveOn[p][id]=1;say("Чайник нагревается на плите.");}return 1;}}
